INSERT INTO public.letters (id, sort_order, title, letter, name, email, programme, cohort, theme, source, status, consent_to_publish) VALUES
  ('c5b97984-0872-5e49-a95e-213fecf71e0f', '1', 'Plan ahead for a day in London', 'There are so many fun things to do in London. Make a good plan and buy tickets in advance. Most importantly, be careful of scams — it is safest to keep your phone in your hand.', 'Zia', NULL, 'Unknown', NULL, 'London', 'collected', 'published', TRUE),
  ('8925a2b4-6d98-5f4e-9fdf-c42f39d90051', '2', 'Look after the basics', 'Eat well, drink water, use the toilet, sleep, and take care of your health.', 'Jassy', NULL, 'Unknown', NULL, 'Wellbeing', 'collected', 'published', TRUE),
  ('81a7e566-462b-5d84-b7db-1525767046a2', '3', 'Check your Oyster balance first', 'Don’t top up your Oyster card blindly.', NULL, NULL, 'Unknown', NULL, 'London', 'collected', 'published', TRUE),
  ('1de61403-d8b8-51ba-b12a-e564693c198c', '4', 'Take a trolley for groceries', 'Definitely get a shopping trolley. It makes grocery shopping much easier.', NULL, NULL, 'Unknown', NULL, 'London', 'collected', 'published', TRUE),
  ('106d6cf6-c455-571e-a656-e7fe99369bc8', '5', 'A note about facing racism', 'If you encounter racism, don’t be afraid. Just walk away and don’t let it affect you.', 'Reese', NULL, 'Unknown', NULL, 'Belonging & safety', 'collected', 'published', TRUE),
  ('13100483-6479-5f96-9dec-59d9972a2e54', '6', 'Start before you feel ready', 'Just do it.', NULL, NULL, 'Unknown', NULL, 'Creative practice', 'collected', 'published', TRUE),
  ('d873f66e-a6cf-53c4-80b1-bfd287b4b878', '7', 'Keep practising English', 'Learn English well.', NULL, NULL, 'Unknown', NULL, 'Language', 'collected', 'published', TRUE),
  ('887ef31d-4da4-579f-b76f-fa21519228bd', '8', 'Start making before you overthink', 'When making work, don’t overthink it or only plan it in your head. Just start making.', 'Jia Yan', NULL, 'Print', NULL, 'Creative practice', 'collected', 'published', TRUE),
  ('9fb460ca-b576-54a0-9129-be3ac0a3b239', '9', 'Find the resources, then follow through', 'RCA has a lot of resources and opportunities, but more importantly, you need to stay self-motivated, actively look for resources, and keep pushing yourself. That is how you can truly discover the unlimited possibilities here.', 'Jiahao Zhou', NULL, 'Service Design', NULL, 'Study & resources', 'collected', 'published', TRUE),
  ('72d3eb5f-c3c9-5eac-aa01-0e25b7a305dc', '10', 'Let experiments take their time', 'Not every exploration needs to become an outcome right away. Some experiences need time before they find their way into your work.', 'Xinyu Wang', NULL, 'Print', NULL, 'Creative practice', 'collected', 'published', TRUE),
  ('f213fc2d-d0c0-58c4-bf29-bb4c1be3a577', '11', 'Move at your own pace', 'When you see that other people are doing a lot of rich and varied work, don’t rush and don’t compare yourself to others.', 'Dami', NULL, 'Sculpture', NULL, 'Wellbeing', 'collected', 'published', TRUE),
  ('dd5be7cf-79da-5ee5-98a6-a1296c2659b6', '12', 'Secure a studio early', 'If you are sure you are coming, try to secure a studio early. It is cheaper that way, and prices will keep rising later.', 'Yanru Xie', NULL, 'Print', NULL, 'Accommodation', 'collected', 'published', TRUE),
  ('db6903b7-4d8b-5968-8292-99e942d3f5e2', '13', 'Plan for what comes after', 'Don’t become too emotionally attached to RCA. Prepare early for your next stage.', 'Jiawei Tian', NULL, 'Unknown', NULL, 'Future planning', 'collected', 'published', TRUE),
  ('8a632c65-2a5c-5eb8-9046-d8ecf83f643b', '14', 'Find your own direction', 'Find your own position and improve your self-motivation.', 'Yaxin Cao', NULL, 'Visual Communication', NULL, 'Study & motivation', 'collected', 'published', TRUE),
  ('eba35061-d611-58bb-968c-571b4cbcbc65', '15', 'You can take time before studying', 'You do not have to continue studying straight away. If you are still unsure about your path, explore slowly before coming to RCA. Work, travel, and see the world. You do not need to follow the crowd in making your choices. RCA will still be here for you.', 'Yiqun Xie Evan', NULL, 'Service Design', NULL, 'Future planning', 'collected', 'published', TRUE),
  ('78f5d87c-0b48-5953-8c32-348f02f1b07c', '16', 'Think past the short-term saving', 'Don’t lose sight of the bigger picture for small gains. Saving a little money may lead to bigger negative consequences.', NULL, NULL, 'Unknown', NULL, 'Money', 'collected', 'published', TRUE),
  ('4b3902b2-0b37-50b0-b2dd-88234d3c6861', '17', 'Rest when you need to', 'Skip class when you need to.', NULL, NULL, 'Unknown', NULL, 'Wellbeing', 'collected', 'published', TRUE),
  ('75f5b7aa-cae3-5354-82f9-0f225c7fa25d', '18', 'Meet people and explore', 'I think socialising and broadening your horizons are the most important parts of studying abroad. You may not learn a huge amount in one year, but you can access more equipment and meet more people, which can create more opportunities for your future.', 'Yulin Zou', NULL, 'Unknown', NULL, 'Belonging', 'collected', 'published', TRUE),
  ('e8a4bab2-71a6-5391-8eca-2fd1d9396cc1', '19', 'Practise working independently', 'You really need to learn how to work independently. Don’t rely too much on your tutors.', NULL, NULL, 'Unknown', NULL, 'Study', 'collected', 'published', TRUE),
  ('492fc12b-89f4-586a-bcd4-0319f150e5be', '20', 'Compare courses and costs', 'Go and study at UAL — it is cheaper and the course lasts longer.', NULL, NULL, 'Unknown', NULL, 'Course choices', 'collected', 'published', TRUE),
  ('5cd003a2-213d-5df5-8ff4-d1d766ae0300', '21', 'Plan study time before deadlines', 'Make a study plan early. Don’t leave everything until the deadline.', NULL, NULL, 'Unknown', NULL, 'Study', 'collected', 'published', TRUE),
  ('b43ea1e4-1eb1-5847-bf7b-e107ed7f3fab', '22', 'Think about how you work', 'Consider whether you are someone who is driven by tasks. If not, don’t come to RCA lightly.', 'Aili Lin (Eille)', NULL, 'Unknown', NULL, 'Course choices', 'collected', 'published', TRUE),
  ('cc7c389e-84ab-5e40-94cc-b7961e7b422f', '23', 'Eat, drink and sleep well', 'Eat well, drink well, and sleep well!', NULL, NULL, 'Unknown', NULL, 'Wellbeing', 'collected', 'published', TRUE),
  ('e6329bcd-a0a6-573b-9023-4ce83973c374', '24', 'Book workshop space early', 'Make sure to book workshops early, otherwise you will not be able to get a place, haha.', NULL, NULL, 'Unknown', NULL, 'Workshop access', 'collected', 'published', TRUE),
  ('9b1abe6b-b0a6-5650-96fb-ddb449d1fae8', '25', 'Let London become your studio', 'If you have no ideas, just go outside and wander around. The whole of London can be your studio.', NULL, NULL, 'Unknown', NULL, 'Creative practice', 'collected', 'published', TRUE),
  ('be91c229-7890-5240-98f5-ad4c94c16fd8', '26', 'Make friends for the right reasons', 'Don’t make friends just for the sake of making friends.', NULL, NULL, 'Unknown', NULL, 'Belonging', 'collected', 'published', TRUE),
  ('7ade597a-2414-5e83-8793-6f689cdb557c', '27', 'Talk across different backgrounds', 'I think it is important to communicate with people from different cultural backgrounds.', NULL, NULL, 'Unknown', NULL, 'Belonging', 'collected', 'published', TRUE)
